// ReverseQUICStatus reports what the VPS can actually observe. A functioning
// Xray process or successful SOCKS UDP ASSOCIATE does NOT prove that the
// domestic Portal is authenticated and registered. End-to-end proof requires
// traffic generated by Windows through its local SOCKS5 listener.
type ReverseQUICStatus struct {
	Enabled         bool    `json:"enabled"`
	State           string  `json:"state"`
	Message         string  `json:"message"`
	CheckedAt       int64   `json:"checkedAt"`
	XrayRunning     bool    `json:"xrayRunning"`
	WarpUDPReady    bool    `json:"warpUdpReady"`
	WarpDetail      string  `json:"warpDetail"`
	ExitReady       bool    `json:"exitReady"`
	ExitDetail      string  `json:"exitDetail"`
	TrafficObserved bool    `json:"trafficObserved"`
	LastTrafficAt   int64   `json:"lastTrafficAt,omitempty"`
	UploadMbps      float64 `json:"uploadMbps"`
	DownloadMbps    float64 `json:"downloadMbps"`
	TrafficDetail   string  `json:"trafficDetail"`
	// No 'portalOnline' field: Xray 26.3.27 exposes no registered reverse
	// worker-state API through its StatsService. Do not invent this signal.
}

type reverseQUICMeter struct {
	sync.Mutex
	process         *xray.Process
	at              time.Time
	lastTrafficAt   time.Time
	trafficObserved bool
	up, down        int64
}

var reverseQUICStatsMeter reverseQUICMeter

// SOCKS probe credentials come only from Xray's active configuration, not
// caller-supplied destinations. Never proxy arbitrary URLs for this status API.
type reverseQUICSOCKS struct {
	Address  string
	Username string
	Password string
}

func lookupReverseSOCKSOutbound(cfg *xray.Config, tag string) (reverseQUICSOCKS, error) {
	var output reverseQUICSOCKS
	var outbounds []struct {
		Tag      string `json:"tag"`
		Protocol string `json:"protocol"`
		Settings struct {
			Servers []struct {
				Address string `json:"address"`
				Port    int    `json:"port"`
				Users   []struct {
					User string `json:"user"`
					Pass string `json:"pass"`
				} `json:"users"`
			} `json:"servers"`
		} `json:"settings"`
	}
	if err := json.Unmarshal(cfg.OutboundConfigs, &outbounds); err != nil {
		return output, fmt.Errorf("解析当前 Xray 出站失败: %w", err)
	}
	for _, outbound := range outbounds {
		if outbound.Tag != tag {
			continue
		}
		if outbound.Protocol != "socks" || len(outbound.Settings.Servers) != 1 {
			return output, fmt.Errorf("出站 %s 不是单个 SOCKS5 服务器", tag)
		}
		srv := outbound.Settings.Servers[0]
		if srv.Port < 1 || srv.Port > 65535 {
			return output, fmt.Errorf("SOCKS5 出站端口无效")
		}
		ip := net.ParseIP(srv.Address)
		if ip == nil || !ip.IsLoopback() {
			return output, fmt.Errorf("SOCKS5 诊断仅允许本机回环地址")
		}
		output.Address = net.JoinHostPort(srv.Address, strconv.Itoa(srv.Port))
		if len(srv.Users) > 0 {
			output.Username = srv.Users[0].User
			output.Password = srv.Users[0].Pass
		}
		return output, nil
	}
	return output, fmt.Errorf("当前 Xray 中未找到 SOCKS5 出站 %s", tag)
}

func socksRead(conn net.Conn, n int) ([]byte, error) {
	buf := make([]byte, n)
	_, err := io.ReadFull(conn, buf)
	return buf, err
}

// checkSOCKS5 probes actual SOCKS5 handshakes. For WARP it additionally
// verifies that UDP ASSOCIATE is accepted. This is a control-plane test and
// does not pretend to be end-to-end QUIC connectivity.
func checkSOCKS5(ctx context.Context, s reverseQUICSOCKS, wantUDP bool) error {
	dialer := &net.Dialer{Timeout: 1200 * time.Millisecond}
	conn, err := dialer.DialContext(ctx, "tcp", s.Address)
	if err != nil {
		return fmt.Errorf("无法连接 SOCKS5 %s: %w", s.Address, err)
	}
	defer conn.Close()
	deadline, ok := ctx.Deadline()
	if !ok {
		deadline = time.Now().Add(1800 * time.Millisecond)
	}
	if err := conn.SetDeadline(deadline); err != nil {
		return err
	}
	methods := []byte{0}
	if s.Username != "" {
		methods = []byte{2}
	}
	if _, err := conn.Write(append([]byte{5, byte(len(methods))}, methods...)); err != nil {
		return fmt.Errorf("SOCKS5 握手发送失败: %w", err)
	}
	reply, err := socksRead(conn, 2)
	if err != nil {
		return fmt.Errorf("SOCKS5 握手无响应: %w", err)
	}
	if reply[0] != 5 || reply[1] != methods[0] {
		return fmt.Errorf("SOCKS5 鉴权方式不匹配/被拒绝")
	}
	if s.Username != "" {
		if len(s.Username) > 255 || len(s.Password) > 255 {
			return errors.New("SOCKS5 凭据长度超限")
		}
		request := append([]byte{1, byte(len(s.Username))}, []byte(s.Username)...)
		request = append(request, byte(len(s.Password)))
		request = append(request, []byte(s.Password)...)
		if _, err := conn.Write(request); err != nil {
			return fmt.Errorf("SOCKS5 用户认证请求失败: %w", err)
		}
		auth, err := socksRead(conn, 2)
		if err != nil || auth[1] != 0 || auth[0] != 1 {
			return errors.New("SOCKS5 用户认证失败")
		}
	}
	if !wantUDP {
		return nil // Final-site egress SOCKS5 TCP readiness; not a website test.
	}

	// RFC 1928, UDP ASSOCIATE for localhost:0 (do not dial any remote host).
	if _, err := conn.Write([]byte{5, 3, 0, 1, 127, 0, 0, 1, 0, 0}); err != nil {
		return fmt.Errorf("发送 UDP ASSOCIATE 失败: %w", err)
	}
	answer, err := socksRead(conn, 4)
	if err != nil {
		return fmt.Errorf("SOCKS5 不支持 UDP ASSOCIATE: %w", err)
	}
	if answer[0] != 5 || answer[1] != 0 {
		return fmt.Errorf("SOCKS5 UDP ASSOCIATE 被拒绝 (REP=%d)", answer[1])
	}
	var remaining int
	switch answer[3] {
	case 1:
		remaining = 4
	case 4:
		remaining = 16
	case 3:
		length, err := socksRead(conn, 1)
		if err != nil {
			return err
		}
		remaining = int(length[0])
	default:
		return errors.New("SOCKS5 UDP ASSOCIATE 返回未知地址类型")
	}
	if _, err := socksRead(conn, remaining+2); err != nil {
		return fmt.Errorf("SOCKS5 UDP ASSOCIATE 返回地址不完整: %w", err)
	}
	return nil
}

func sampleReverseQUICOutboundTraffic(process *xray.Process, now time.Time) (bool, time.Time, float64, float64, string) {
	traffics, err := process.GetTraffic(false) // read-only, never reset stats
	if err != nil {
		return false, time.Time{}, 0, 0, "Xray 业务计数器暂不可读取: " + err.Error()
	}
	var up, down int64
	found := false
	for _, traffic := range traffics {
		if !traffic.IsInbound && traffic.Tag == reverseQUICOutboundTag {
			found = true
			up, down = traffic.Up, traffic.Down
			break
		}
	}
	if !found {
		return false, time.Time{}, 0, 0, "尚未产生 Hysteria2 出站业务计数（未证实隧道在线）"
	}
	reverseQUICStatsMeter.Lock()
	defer reverseQUICStatsMeter.Unlock()
	meter := &reverseQUICStatsMeter
	if meter.process != process {
		meter.process = process
		meter.at = time.Time{}
		meter.lastTrafficAt = time.Time{}
		meter.trafficObserved = false
	}
	var upRate, downRate float64
	if !meter.at.IsZero() && up >= meter.up && down >= meter.down {
		elapsed := now.Sub(meter.at).Seconds()
		if elapsed > .1 {
			deltaUp, deltaDown := up-meter.up, down-meter.down
			upRate = float64(deltaUp) * 8 / 1e6 / elapsed
			downRate = float64(deltaDown) * 8 / 1e6 / elapsed
			if deltaUp > 0 || deltaDown > 0 {
				meter.lastTrafficAt = now
				meter.trafficObserved = true
			}
		}
	}
	// Existing x-ui traffic collectors may reset StatsService counters.
	// Counter resets are never treated as negative traffic or an outage.
	if up < meter.up || down < meter.down {
		upRate, downRate = 0, 0
	}
	meter.at, meter.up, meter.down = now, up, down
	return meter.trafficObserved, meter.lastTrafficAt, upRate, downRate,
		"从 Xray Hysteria2 出站业务计数器采样；非主动测速，不代表公网极限带宽"
}

func (s *ReverseQUICBridgeService) Status(ctx context.Context) (ReverseQUICStatus, error) {
	now := time.Now()
	result := ReverseQUICStatus{
		CheckedAt: now.Unix(), State: "disabled",
		Message:    "此配置未启用；旧 FRP 和 WARP 配置不受影响",
		WarpDetail: "未检测", ExitDetail: "未检测",
		TrafficDetail: "尚无业务样本",
	}
	cfg, err := s.Get()
	if err != nil {
		return result, err
	}
	result.Enabled = cfg.Enabled
	if !cfg.Enabled {
		return result, nil
	}
	lock.Lock()
	process := p
	running := process != nil && process.IsRunning()
	var activeConfig *xray.Config
	if running {
		activeConfig = process.GetConfig()
	}
	lock.Unlock()
	result.XrayRunning = running
	if !running {
		result.State, result.Message = "down", "x-ui 管理的 Xray 已停止：反向隧道离线"
		return result, nil
	}

	warp, err := lookupReverseSOCKSOutbound(activeConfig, cfg.TransportProxyTag)
	if err != nil {
		result.State, result.Message, result.WarpDetail = "down", "隧道 WARP 出站配置错误", err.Error()
		return result, nil
	}
	probeCtx, cancel := context.WithTimeout(ctx, 1800*time.Millisecond)
	defer cancel()
	if err := checkSOCKS5(probeCtx, warp, true); err != nil {
		result.State, result.Message, result.WarpDetail = "down", "WARP SOCKS5 握手或 UDP ASSOCIATE 失败：隧道传输异常", err.Error()
		return result, nil
	}
	result.WarpUDPReady = true
	result.WarpDetail = "WARP SOCKS5 已接受 UDP ASSOCIATE（不等于境内 QUIC 已完成认证）"

	if cfg.EgressMode == "socks5" {
		egress, err := lookupReverseSOCKSOutbound(activeConfig, reverseQUICEgressTag)
		if err != nil {
			result.State, result.Message, result.ExitDetail = "down", "真实网站出口 SOCKS5 配置错误", err.Error()
			return result, nil
		}
		exitCtx, exitCancel := context.WithTimeout(ctx, 1800*time.Millisecond)
		defer exitCancel()
		if err := checkSOCKS5(exitCtx, egress, false); err != nil {
			result.State, result.Message, result.ExitDetail = "down", "真实出口 SOCKS5 握手失败", err.Error()
			return result, nil
		}
		result.ExitReady, result.ExitDetail = true, "本机 SOCKS5 握手成功；未测试目标网站"
	} else {
		result.ExitReady, result.ExitDetail = true, "freedom 直连模式；未测试目标网站"
	}

	result.TrafficObserved, _, result.UploadMbps, result.DownloadMbps, result.TrafficDetail =
		sampleReverseQUICOutboundTraffic(process, now)
	reverseQUICStatsMeter.Lock()
	last := reverseQUICStatsMeter.lastTrafficAt
	reverseQUICStatsMeter.Unlock()
	if !last.IsZero() {
		result.LastTrafficAt = last.Unix()
	}
	if result.LastTrafficAt > 0 && now.Sub(last) < 45*time.Second {
		result.State, result.Message = "active", "最近 45 秒检测到反向隧道业务流量；当前未检测到本机代理故障"
	} else {
		result.State = "unknown"
		result.Message = "Xray/WARP SOCKS5 可用，但暂无近期反向业务证据；闲置与掉线无法仅凭 VPS 区分，请在 Windows 1081 端口执行探测"
	}
	return result, nil
}
